enum _Trailing { more, play, pause, none, check, chev, checkbox, plus }

/// 行：卡片 13 圆角 / 可选序号 / 48dp 点击区（与设计稿逐像素对应）
class _Row extends StatelessWidget {
  const _Row({
    required this.p,
    required this.s,
    required this.title,
    this.sub,
    this.index,
    this.trailing = _Trailing.more,
  });

  final DesignPalette p;
  final _Strings s;
  final String title;
  final String? sub;
  final int? index;
  final _Trailing trailing;

  @override
  Widget build(BuildContext context) {
    final Widget lead = index == null
        ? Container(
            width: 40,
            height: 40,
            decoration: BoxDecoration(
                color: p.surface2, borderRadius: BorderRadius.circular(11)),
            child: Icon(Icons.music_note, size: 20, color: p.muted),
          )
        : SizedBox(
            width: 24,
            child: Text('$index',
                textAlign: TextAlign.center,
                style: TextStyle(fontSize: 12, color: p.dim)),
          );
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Material(
        color: p.surface,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(DesignPalette.cardRadius),
          side: BorderSide(color: p.line),
        ),
        child: InkWell(
          onTap: () {},
          borderRadius: BorderRadius.circular(DesignPalette.cardRadius),
          child: SizedBox(
            height: 62,
            child: Row(
              children: <Widget>[
                const SizedBox(width: 10),
                lead,
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: <Widget>[
                      Text(title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              fontSize: 13,
                              fontWeight: FontWeight.w600,
                              color: p.text)),
                      if (sub != null) ...<Widget>[
                        const SizedBox(height: 3),
                        Text(sub!,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(fontSize: 11, color: p.muted)),
                      ],
                      
                    ],
                  ),
                ),
                _trailingWidget(),
                const SizedBox(width: 4),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _trailingWidget() {
    switch (trailing) {
      case _Trailing.more:
        return IconButton(
            onPressed: null,
            icon: Icon(Icons.more_vert, size: 20, color: p.muted),
            tooltip: '更多');
      case _Trailing.play:
        return IconButton(
            onPressed: null,
            icon: Icon(Icons.play_circle_outline, size: 24, color: p.accent),
            tooltip: '播放');
      case _Trailing.pause:
        return IconButton(
            onPressed: null,
            icon: Icon(Icons.pause_circle_filled, size: 24, color: p.primary),
            tooltip: '暂停');
      case _Trailing.check:
        return Icon(Icons.check, size: 20, color: p.ok);
      case _Trailing.plus:
        return Icon(Icons.add, size: 20, color: p.accent);
      case _Trailing.chev:
        return Icon(Icons.chevron_right, size: 18, color: p.dim);
      case _Trailing.checkbox:
        return Container(
          width: 20,
          height: 20,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(5),
            border: Border.all(color: p.muted),
          ),
        );
      case _Trailing.none:
        return const SizedBox(width: 8);
    }
  }
}
